/*
 * El día de operación y su rango en el reloj del sistema.
 *
 * El día lo manda el tablero ('YYYY-MM-DD', ya resuelto en hora de Ciudad de
 * México). Si no viene —la corrida programada—, se calcula acá con la misma
 * zona. Nunca con el reloj del servidor de n8n ni del de SQL Server: los tres
 * pueden estar en zonas distintas.
 *
 * El rango sale en el reloj de RapiboyData, que guarda las fechas en hora de
 * Argentina: el día 21 en México va de las 03:00 del 21 a las 03:00 del 22 en
 * ese reloj. Se calcula con Intl y no restando tres horas, porque esa
 * diferencia es una circunstancia —ninguno de los dos países usa horario de
 * verano hoy— y no una regla.
 *
 * Lo único que entra a la consulta son estos tres textos, y los tres salen de
 * acá con un formato fijo: el día se valida con una expresión regular antes
 * de usarlo, así que nada que mande el navegador llega crudo a SQL Server.
 */
const ZONA_OPERACION = 'America/Mexico_City';
const ZONA_SISTEMA = 'America/Argentina/Buenos_Aires';

const cuerpo = $json?.body ?? $json ?? {};
const pedido = typeof cuerpo.dia === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(cuerpo.dia)
  ? cuerpo.dia
  : null;

const partes = (momento, zona) => Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', {
    timeZone: zona,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(momento).map((p) => [p.type, p.value]),
);

/** El reloj de pared de `zona` en ese instante, como 'YYYY-MM-DD HH:MM:SS'. */
const reloj = (momento, zona) => {
  const p = partes(momento, zona);
  return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}:${p.second}`;
};

/**
 * El instante en que empieza `dia` en `zona`. Se corrige el desfase hasta que
 * el reloj de esa zona marque la medianoche: dos vueltas alcanzan, la tercera
 * es margen para un día con cambio de hora.
 */
const inicioDelDia = (dia, zona) => {
  const [anio, mes, fecha] = dia.split('-').map(Number);
  const objetivo = Date.UTC(anio, mes - 1, fecha);
  let instante = objetivo;
  for (let vuelta = 0; vuelta < 3; vuelta += 1) {
    const visto = Date.parse(reloj(new Date(instante), zona).replace(' ', 'T') + 'Z');
    instante -= visto - objetivo;
  }
  return new Date(instante);
};

const diaSiguiente = (dia) => {
  const [anio, mes, fecha] = dia.split('-').map(Number);
  return new Date(Date.UTC(anio, mes - 1, fecha + 1)).toISOString().slice(0, 10);
};

const hoy = (() => {
  const p = partes(new Date(), ZONA_OPERACION);
  return `${p.year}-${p.month}-${p.day}`;
})();
const dia = pedido ?? hoy;

return [{
  json: {
    dia,
    desde: reloj(inicioDelDia(dia, ZONA_OPERACION), ZONA_SISTEMA),
    hasta: reloj(inicioDelDia(diaSiguiente(dia), ZONA_OPERACION), ZONA_SISTEMA),
    // Una marca para toda la corrida: cada fila que escriba la lleva igual.
    sincronizado_en: new Date().toISOString(),
    origen: pedido ? 'tablero' : 'horario',
  },
}];

/*
 * Colectas a columnas de Postgres.
 *
 * Las fechas ya llegan como instantes ISO con zona —la consulta las convierte
 * con AT TIME ZONE— así que acá solo se validan. Día y marca de la corrida
 * vienen pegados a cada fila: ningún nodo va a buscarlos a otro lado.
 *
 * De Colecta.IdPedidos se guarda cuántos ids hay, no la lista: es texto libre
 * que el sistema llena con ids separados por coma, y para la pantalla alcanza
 * con el número. Se cuentan los ids distintos, así un id repetido no infla la
 * cantidad esperada.
 */
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};
const entero = (v) =>
  v === null || v === undefined || v === '' || !Number.isFinite(Number(v))
    ? null
    : Math.trunc(Number(v));
const marca = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const hora = (v) => {
  const t = texto(v);
  return t && /^\d{2}:\d{2}$/.test(t) ? t : null;
};
const booleano = (v) => (v === null || v === undefined || v === '' ? null : Boolean(v));
const pedidos = (v) => {
  const t = texto(v);
  return t ? new Set(t.match(/\d+/g) ?? []).size : null;
};

/*
 * La misma regla que `coordenadaValida` en web/src/lib/tracker.ts: fuera de
 * rango o el (0, 0) de un equipo sin señal no son una posición.
 */
const coordenada = (lat, lon) => {
  const a = Number(lat);
  const b = Number(lon);
  if (lat === null || lon === null || lat === undefined || lon === undefined) return null;
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  if (a < -90 || a > 90 || b < -180 || b > 180) return null;
  if (a === 0 && b === 0) return null;
  return { lat: a, lon: b };
};

return $input
  .all()
  .map(({ json: r }) => {
    const tienda = coordenada(r.LatitudTienda, r.LongitudTienda);
    return {
      json: {
        id_colecta: Number(r.IdColecta),
        fecha_operacion: String(r.Dia ?? '').slice(0, 10),
        id_estado: entero(r.IdEstado),
        creada_en: marca(r.CreadaEn),
        solicitada_en: marca(r.SolicitadaEn),
        colectada_en: marca(r.ColectadaEn),
        llego_deposito_en: marca(r.LlegoDepositoEn),
        cancelada_en: marca(r.CanceladaEn),
        estado_desde: marca(r.EstadoDesde),
        aceptada_en: marca(r.AceptadaEn),
        en_camino_en: marca(r.EnCaminoEn),
        en_local_en: marca(r.EnLocalEn),
        retirada_en: marca(r.RetiradaEn),
        finalizada_en: marca(r.FinalizadaEn),
        en_deposito_en: marca(r.EnDepositoEn),
        hora_desde: hora(r.HoraDesde),
        hora_hasta: hora(r.HoraHasta),
        id_turno: entero(r.IdTurno),
        id_reserva: entero(r.IdReserva),
        reserva_cancelada: booleano(r.ReservaCancelada),
        id_motoboy: entero(r.IdMotoboy),
        id_motoboy_reserva: entero(r.IdMotoboyReserva),
        id_seller: entero(r.IdSeller),
        seller: texto(r.Seller),
        direccion_seller: texto(r.DireccionSeller),
        latitud_tienda: tienda?.lat ?? null,
        longitud_tienda: tienda?.lon ?? null,
        cantidad_pedidos: pedidos(r.IdPedidos),
        paquetes_solicitados: entero(r.PaquetesSolicitados),
        paquetes_colectados: entero(r.PaquetesColectados),
        cantidad_bultos: entero(r.CantidadBultos),
        id_deposito: entero(r.IdDeposito),
        depositos_visitados: texto(r.DepositosVisitados),
        comentario: texto(r.Comentario),
        sincronizado_en: marca(r.SincronizadoEn) ?? new Date().toISOString(),
      },
    };
  })
  .filter(
    (i) =>
      Number.isFinite(i.json.id_colecta) &&
      i.json.id_colecta > 0 &&
      /^\d{4}-\d{2}-\d{2}$/.test(i.json.fecha_operacion),
  );

/*
 * Repartidores a columnas de Postgres: uno por persona, aunque tenga diez
 * colectas. La consulta repite su posición en cada fila de colecta; acá se
 * queda la primera, que es la misma en todas.
 *
 * El repartidor es el de la colecta y, si falta, el de su reserva: el mismo
 * COALESCE con el que la consulta une Motoboy.
 *
 * Un repartidor sin coordenadas válidas se guarda igual, sin posición. Está
 * operando y tiene que aparecer en la lista: «salió y no está transmitiendo»
 * es un dato. Lo que no se hace es dibujarlo donde no está.
 */
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};
const marca = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const coordenada = (lat, lon) => {
  const a = Number(lat);
  const b = Number(lon);
  if (lat === null || lon === null || lat === undefined || lon === undefined) return null;
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  if (a < -90 || a > 90 || b < -180 || b > 180) return null;
  if (a === 0 && b === 0) return null;
  return { lat: a, lon: b };
};

const vistos = new Map();

for (const { json: r } of $input.all()) {
  const id = Number(r.IdMotoboy ?? r.IdMotoboyReserva);
  if (!Number.isFinite(id) || id <= 0 || vistos.has(id)) continue;

  const dia = String(r.Dia ?? '').slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dia)) continue;

  const punto = coordenada(r.LatitudRepartidor, r.LongitudRepartidor);
  vistos.set(id, {
    json: {
      id_motoboy: id,
      fecha_operacion: dia,
      nombre: texto(r.NombreRepartidor),
      apellido: texto(r.ApellidoRepartidor),
      latitud: punto?.lat ?? null,
      longitud: punto?.lon ?? null,
      posicion_en: punto ? marca(r.PosicionEn) : null,
      sincronizado_en: marca(r.SincronizadoEn) ?? new Date().toISOString(),
    },
  });
}

return [...vistos.values()];

/*
 * Las posiciones para el recorrido: una por repartidor y por reporte.
 *
 * RapiboyData no guarda un historial de posiciones, así que el recorrido se
 * arma guardando lo que ve cada corrida. La clave es (repartidor, momento del
 * reporte): si el teléfono no volvió a reportar desde la corrida anterior, el
 * upsert cae sobre la misma fila y no se agrega nada.
 *
 * Solo entran posiciones válidas y reportadas **ese día** en México. Un
 * teléfono que no reporta desde ayer tiene la posición de ayer, y sumarla al
 * recorrido de hoy dibujaría un tramo que no ocurrió.
 */
const ZONA_OPERACION = 'America/Mexico_City';

const coordenada = (lat, lon) => {
  const a = Number(lat);
  const b = Number(lon);
  if (lat === null || lon === null || lat === undefined || lon === undefined) return null;
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  if (a < -90 || a > 90 || b < -180 || b > 180) return null;
  if (a === 0 && b === 0) return null;
  return { lat: a, lon: b };
};

const diaEnMexico = (instante) =>
  new Intl.DateTimeFormat('en-CA', {
    timeZone: ZONA_OPERACION, year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(instante);

const vistos = new Map();

for (const { json: r } of $input.all()) {
  const id = Number(r.IdMotoboy ?? r.IdMotoboyReserva);
  if (!Number.isFinite(id) || id <= 0 || vistos.has(id)) continue;

  const dia = String(r.Dia ?? '').slice(0, 10);
  const punto = coordenada(r.LatitudRepartidor, r.LongitudRepartidor);
  const momento = r.PosicionEn ? new Date(r.PosicionEn) : null;
  if (!punto || !momento || Number.isNaN(momento.getTime())) continue;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dia) || diaEnMexico(momento) !== dia) continue;

  vistos.set(id, {
    json: {
      id_motoboy: id,
      posicion_en: momento.toISOString(),
      fecha_operacion: dia,
      latitud: punto.lat,
      longitud: punto.lon,
    },
  });
}

return [...vistos.values()];
